mapper.select:
SELECT id, name, reg_dtt, last_login, pwd_change_dtt, quit_dtt, roles, wrong_count, quit_reason, status, IF (status = 1, '사용중', '말소') as status_name, TIMESTAMPDIFF(MONTH, pwd_change_dtt, now()) as pwd_age, TIMESTAMPDIFF(MONTH, last_login, now()) as login_age FROM t_manager
ORDER BY reg_dtt DESC
LIMIT ${ offset }, ${ perPage }

SELECT count(*)
FROM t_manager
WHERE id = #{ id }

mapper.update:
UPDATE t_manager
SET
  status      = 2,
  quit_dtt    = now(),
  quit_reason = #{ quitReason }
WHERE id = #{ id }

UPDATE t_manager
SET name = #{ name }, roles = #{ roles }

  ,pwd = #{ pwd }, pwd_change_dtt = now()

WHERE id = #{ id }

UPDATE t_manager
SET
  pwd_change_dtt = now(),
  pwd            = #{ newPwd }
WHERE id = #{ id }

mapper.select:
SELECT id, name, dtt, ip_addr FROM t_login_history r LEFT JOIN t_manager ON r.actor = t_manager.id
ORDER BY dtt DESC
LIMIT ${ offset }, ${ perPage }

SELECT id, name, menu, action, dtt, ip_addr, size FROM t_access_history r LEFT JOIN t_manager ON r.actor = t_manager.id
AND action NOT LIKE '%조회%' ORDER BY dtt DESC
LIMIT ${ offset }, ${ perPage }
